import {LIMITS,SECTORS,STAGES,SOURCES,safeUrl,escapeHtml as esc,money,numberOrNull,computeFinance,matchVendors,evaluateGates,scoreOpportunity,realizedContribution,activePortfolioExposure,isOverdue,forecastCashWaterfall} from "./core.js";
import {DEMO_OPPORTUNITIES,DEMO_VENDORS} from "./seed.js";

const STORAGE_KEY="watchtower-ai-browser-v1";
const NAV={command:"COMMAND CENTER",hunt:"OPPORTUNITY HUNT",partners:"PARTNER BENCH",decisions:"DECISION DESK",sources:"INTELLIGENCE SOURCES",settings:"RULES & SETTINGS"};
const root=document.getElementById("viewRoot"),modalRoot=document.getElementById("modalHost"),sidebar=document.getElementById("sidebar");
const clone=x=>JSON.parse(JSON.stringify(x));
const initial=()=>({mode:"demo",demo:{opportunities:clone(DEMO_OPPORTUNITIES),vendors:clone(DEMO_VENDORS),transactions:[],activity:[]},live:{opportunities:[],vendors:[],transactions:[],activity:[]},filters:{search:"",sector:"all",stage:"all",partnerSearch:""}});
let state=load(),detailId=null,detailTab="overview",previousFocus=null;
function load(){try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){const s=JSON.parse(raw);if(s&&["demo","live"].includes(s.mode)&&s.live&&s.demo&&Array.isArray(s.live.opportunities)&&Array.isArray(s.live.vendors)&&Array.isArray(s.live.transactions)){s.filters=s.filters||{search:"",sector:"all",stage:"all",partnerSearch:""};return s;}}}catch(err){console.warn("Storage unavailable",err);}return initial();}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{toast("Browser storage is unavailable. Export a backup to keep your data.",true);}}
function work(){return state[state.mode];}
function opportunities(){return work().opportunities;}
function vendors(){return work().vendors;}
function activity(){return work().activity;}
function view(){const h=location.hash.slice(1).split("?")[0];return NAV[h]?h:"command";}
function setView(v){if(!NAV[v])return;location.hash=v;render();closeNav();}
function stamp(){return new Date().toLocaleString("en-US",{month:"short",day:"numeric",hour:"numeric",minute:"2-digit"});}
function dateFmt(s){if(!s)return"Not set";const d=new Date(s+"T12:00:00");return Number.isFinite(d.getTime())?d.toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"}):"Invalid";}
function log(message,id=""){work().activity.unshift({id:"log-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2,6),message:String(message).slice(0,300),dealId:id,at:new Date().toISOString()});work().activity=work().activity.slice(0,150);save();}
function uuid(prefix){return prefix+"-"+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2,9));}
function short(str,n=78){const t=String(str??"");return t.length>n?t.slice(0,n-1)+"…":t;}
function tag(label,kind="muted"){return '<span class="tag tag-'+kind+'">'+esc(label)+'</span>';}
function sectorTag(s){return tag(SECTORS[s]||"Other",s==="digital"?"blue":s==="government"?"amber":"muted");}
function sourceLink(d){const u=safeUrl(d.sourceUrl);return u?'<a class="text-link" href="'+esc(u)+'" target="_blank" rel="noopener noreferrer">Original source ↗</a>':'<span class="tiny">'+(d.demo?"Fictional scenario • no source":"No source attached")+'</span>';}
function financialStatus(d,exposure=0){const g=evaluateGates(d,vendors(),exposure),f=g.finance;return {g,f,score:scoreOpportunity(d,vendors(),exposure)};}
function demoNote(){return state.mode==="demo"?'<div class="demo-banner"><strong>◈ DEMO SANDBOX</strong> — These buyers, vendors and figures are entirely fictional. Explore the workflow without treating any record as a real lead, quote or earning. Switch to <strong>Live workspace</strong> in Settings to record actual research.</div>':'<div class="notice" style="margin-bottom:20px"><strong>LOCAL LIVE WORKSPACE</strong> — Entries are self-reported, not independently verified by Watchtower. Data is stored only on this browser and will be lost if its storage is cleared. Do not enter confidential information.</div>';}
function header(kicker,title,sub,actions=""){return '<div class="page-head"><div><p class="kicker">'+esc(kicker)+'</p><h1>'+esc(title)+'</h1><p class="head-sub">'+esc(sub)+'</p></div><div class="head-actions">'+actions+'</div></div>';}
function btn(label,action,id="",style="btn-ghost",extra=""){return '<button type="button" class="btn '+style+'" data-action="'+esc(action)+'"'+(id?' data-id="'+esc(id)+'"':'')+' '+extra+'>'+label+'</button>';}
function rowDetail(label,value){return '<div class="statline"><span>'+esc(label)+'</span><strong>'+value+'</strong></div>';}
function metric(name,value,footer,icon="◈",progress=null){return '<div class="metric"><div class="metric-label">'+esc(name)+'<span class="metric-icon">'+icon+'</span></div><div class="metric-number num">'+esc(value)+'</div><div class="metric-footer">'+esc(footer)+'</div>'+(progress===null?"":'<progress max="100" value="'+Math.min(100,Math.max(0,progress))+'"></progress>')+'</div>';}
function render(){const current=view();document.getElementById("pageBreadcrumb").textContent=NAV[current];document.getElementById("modeChip").textContent=state.mode==="demo"?"DEMO SANDBOX":"LOCAL WORKSPACE";document.getElementById("navOpportunityCount").textContent=opportunities().length;
document.querySelectorAll(".nav-link[data-view]").forEach(b=>{b.classList.toggle("active",b.dataset.view===current);b.setAttribute("aria-current",b.dataset.view===current?"page":"false");});
root.innerHTML=({command:renderCommand,hunt:renderHunt,partners:renderPartners,decisions:renderDecisions,sources:renderSources,settings:renderSettings}[current])();}
function renderCommand(){
 const o=opportunities(),w=work(),realized=realizedContribution(w.transactions.filter(t=>(t.date||"").slice(0,7)===new Date().toISOString().slice(0,7))),active=activePortfolioExposure(o),target=LIMITS.monthlyTarget;
 const qualified=o.filter(d=>!d.demo&&evaluateGates(d,vendors(),activePortfolioExposure(o,d.id)).passed).length;
 const sorted=[...o].sort((a,b)=>scoreOpportunity(b,vendors())-scoreOpportunity(a,vendors())).slice(0,5);
 const upcoming=[...o].filter(d=>d.deadline&&!["LOST","ARCHIVED"].includes(d.stage)).sort((a,b)=>a.deadline.localeCompare(b.deadline)).slice(0,4);
 return header("YOUR PRIVATE INTELLIGENCE DESK","Find leverage. Not more work.","Opportunity intelligence, execution partners and cash discipline—designed around your decisions.",btn("＋ New opportunity","add-opp","","btn-primary")+btn("↗ Switch workspace","go-settings"))+
 demoNote()+
 '<div class="banner"><div class="tag">◉ MISSION DIRECTIVE</div><h2>Hunt the opportunity. Outsource the execution.</h2><p>Default thresholds: $1,000 maximum conservative exposure per deal and across active deals, 25% contribution margin, and no external commitments without owner approval.</p></div>'+
 '<div class="grid metrics">'+metric("REALIZED CONTRIBUTION",money(realized),"Goal "+money(target)+" / month · recorded cash only","↗",realized/target*100)+metric("LEADS IN WORKSPACE",String(o.length),state.mode==="demo"?"All sample scenarios":"Manual entries","◎")+metric("APPROVAL-READY",String(qualified),"Passing every verification and finance gate","◈")+metric("ACTIVE CASH EXPOSURE",money(active),"Combined limit "+money(LIMITS.portfolioExposure),"◇",active/LIMITS.portfolioExposure*100)+'</div>'+
 '<div class="grid split"><section class="panel"><div class="panel-title"><h2>Opportunity radar</h2>'+btn("View all →","go-hunt","","btn-sm btn-ghost")+'</div><p class="panel-sub">Priority is research usefulness, not a prediction of profit.</p>'+renderRows(sorted,false)+'</section><section class="panel"><div class="panel-title"><h2>Next checkpoints</h2>'+tag("READ-ONLY","muted")+'</div>'+
 (upcoming.length?upcoming.map(d=>'<div class="list-card"><div><div class="item-title">'+esc(short(d.title,38))+'</div><div class="item-meta">'+esc(dateFmt(d.deadline))+(isOverdue(d)?' · <span style="color:var(--red)">OVERDUE</span>':'')+'</div></div>'+btn("Inspect","open-opp",d.id,"btn-sm btn-ghost")+'</div>').join(""):'<div class="empty-state">No deadlines yet.<br>Import a verified notice to begin.</div>')+
 '<div class="vdiv"></div><div class="panel-title"><h2>Recent desk activity</h2></div>'+(activity().length?activity().slice(0,4).map(a=>'<div class="event"><div class="event-dot"></div><div><h4>'+esc(short(a.message,85))+'</h4><time>'+esc(a.at.slice(0,10))+'</time></div></div>').join(""):'<p class="small">Decisions and research changes are logged here—locally, on this device.</p>')+'</section></div>'+
 '<div class="section-row"><h2>Research allocation</h2><span class="tiny">OPERATING PRIORITIES • NOT FORECAST RETURNS</span></div><div class="grid three">'+[{n:"DIGITAL SERVICES",p:60,d:"Near-term client work with delivery partners"},{n:"GOVERNMENT",p:25,d:"Procurement, teaming, and compliance research"},{n:"AI VENTURES",p:15,d:"Validate customer demand before building"}].map(x=>'<div class="panel"><div class="item-meta">'+x.n+'</div><h2 style="margin:8px 0">'+x.p+'% <span class="tiny">RESEARCH EFFORT</span></h2><div class="meter"><div style="width:'+x.p+'%"></div></div><p class="small" style="margin:13px 0 0">'+x.d+'</p></div>').join("")+'</div>';
}
function renderRows(rows,wide=true){if(!rows.length)return '<div class="empty-state"><div class="empty-icon">◎</div>No leads in this workspace. Start at Intelligence Sources, locate an active buyer, capture original evidence, and shortlist three execution partners before requesting quotations.</div>';return '<div class="table-scroll"><table class="data-table"><thead><tr><th>Opportunity</th><th>Sector</th><th>Source</th><th>Priority</th><th>Stage</th><th></th></tr></thead><tbody>'+rows.map(d=>{const sc=scoreOpportunity(d,vendors());return '<tr><td><div class="item-title">'+esc(short(d.title,55))+'</div><div class="item-meta">'+esc(short(d.buyer||"Unknown buyer",36))+(d.demo?' · SYNTHETIC':'')+'</div></td><td>'+sectorTag(d.sector)+'</td><td>'+sourceLink(d)+'</td><td><span class="score-circle '+(sc<65?"muted-score":"")+'">'+sc+'</span></td><td>'+tag(d.stage.replaceAll("_"," "),"muted")+'</td><td>'+btn("Inspect →","open-opp",d.id,"btn-sm btn-ghost")+'</td></tr>';}).join("")+'</tbody></table></div>';}
function filtered(){const f=state.filters||{},q=(f.search||"").trim().toLowerCase();return opportunities().filter(d=>(!q||[d.title,d.buyer,d.description,d.source].some(s=>String(s||"").toLowerCase().includes(q)))&&(f.sector==="all"||!f.sector||d.sector===f.sector)&&(f.stage==="all"||!f.stage||d.stage===f.stage)).sort((a,b)=>scoreOpportunity(b,vendors())-scoreOpportunity(a,vendors()));}
function renderHunt(){const f=state.filters||{};return header("DISCOVER / FILTER / PRIORITIZE","Opportunity hunt","One pipeline across digital services, government contracting and AI venture research.",btn("＋ Add opportunity","add-opp","","btn-primary")+btn("Export CSV","export-csv"))+demoNote()+
 '<div class="panel"><div class="panel-title"><h2>Intelligence inbox</h2>'+tag(opportunities().length+" RECORDS","muted")+'</div><div class="filters"><div class="search-box"><input class="input" id="huntSearch" type="search" placeholder="Search opportunities, buyers, descriptions…" value="'+esc(f.search||"")+'" aria-label="Search opportunities"></div><select class="select filter-select" id="sectorFilter" aria-label="Sector"><option value="all">All sectors</option>'+Object.entries(SECTORS).map(([k,v])=>'<option value="'+k+'" '+(f.sector===k?"selected":"")+'>'+v+'</option>').join("")+'</select><select class="select filter-select" id="stageFilter" aria-label="Stage"><option value="all">All stages</option>'+STAGES.map(s=>'<option value="'+s+'" '+(f.stage===s?"selected":"")+'>'+s.replaceAll("_"," ")+'</option>').join("")+'</select></div><div id="opportunityResults">'+renderRows(filtered())+'</div></div>'+
 '<p class="small" style="margin-top:15px">Every legitimate opportunity needs its own original source. Research scores do not certify authenticity or guarantee profit.</p>';}
function renderPartners(){const q=(state.filters?.partnerSearch||"").toLowerCase(),list=vendors().filter(v=>[v.name,v.city,...(v.skills||[])].some(s=>String(s||"").toLowerCase().includes(q)));return header("THE EXECUTION NETWORK","Partner bench","Build a qualified supplier network so you can own the opportunity without performing every task.",btn("＋ Add partner","add-vendor","","btn-primary"))+demoNote()+
 '<div class="notice" style="margin-bottom:20px">Partner listings are research candidates—not signed subcontractors. Certifications, capacity, rates, references and availability require independent confirmation. No outreach is sent by this app.</div>'+
 '<div class="filters"><div class="search-box"><input id="partnerSearch" type="search" class="input" value="'+esc(state.filters?.partnerSearch||"")+'" placeholder="Search partners and skills…" aria-label="Search vendors"></div></div>'+
 (list.length?'<div class="grid three">'+list.map(v=>'<article class="vendor-card"><div class="card-head"><div><div class="kicker" style="margin:0 0 7px">'+(v.demo?"FICTIONAL PARTNER":"RESEARCH PARTNER")+'</div><h3>'+esc(v.name)+'</h3><div class="item-meta">'+esc(v.city||"Location not entered")+'</div></div>'+tag(v.verified?"SELF-MARKED VERIFIED":"UNVERIFIED",v.verified?"":"amber")+'</div><div class="vendor-skills">'+(v.skills||[]).map(s=>'<span class="skill">'+esc(s)+'</span>').join("")+'</div><div class="statline"><span>Indicative cost</span><strong>'+ (numberOrNull(v.estimatedCost)!==null?money(v.estimatedCost):"Unknown")+'</strong></div><div class="statline"><span>Availability</span>'+tag(v.availability||"unknown",v.availability==="available"?"":"amber")+'</div><p class="small">'+esc(short(v.notes||"No due diligence notes",150))+'</p><div class="button-row">'+btn("Review partner","edit-vendor",v.id,"btn-sm btn-ghost")+(safeUrl(v.website)?'<a class="btn btn-sm btn-ghost" href="'+esc(safeUrl(v.website))+'" target="_blank" rel="noopener noreferrer">Website ↗</a>':'')+'</div></article>').join("")+'</div>':'<div class="panel empty-state">No partner profiles found. Add a verified source and capabilities to start building the bench.</div>');}
function renderDecisions(){const all=opportunities().filter(d=>!["ARCHIVED","LOST"].includes(d.stage)).sort((a,b)=>scoreOpportunity(b,vendors())-scoreOpportunity(a,vendors())).slice(0,LIMITS.maxWeeklyBrief);
 return header("FOUNDER'S REVIEW / MAX FIVE","Decision desk","Only you authorize the next step. No automatic vendor outreach, proposal submission or spending.",btn("＋ New lead","add-opp","","btn-primary")+btn("↓ Weekly brief","export-brief"))+demoNote()+
 '<div class="notice warning" style="margin-bottom:20px">An approval here only changes a local research stage. It does not create a binding agreement, send an email, authorize payment or bid on a solicitation.</div>'+
 (all.length?all.map(d=>{const portfolio=activePortfolioExposure(opportunities(),d.id),{g,f,score}=financialStatus(d,portfolio);
 return '<article class="decision-card"><div class="card-head"><div><div class="kicker">'+esc(SECTORS[d.sector]||"Other")+(d.demo?" / SIMULATION":" / RESEARCH")+'</div><h3>'+esc(d.title)+'</h3><p class="small">'+esc(d.buyer||"Buyer unknown")+' · '+esc(d.stage.replaceAll("_"," "))+'</p></div><span class="score-circle">'+score+'</span></div><div class="decision-grid"><div class="tile"><span>PROJECT PRICE</span><strong>'+ (f.price!==null?money(f.price):"Unknown")+'</strong></div><div class="tile"><span>CONTRIBUTION*</span><strong class="'+(f.contribution>=0?"money":"")+'">'+(f.known?money(f.contribution):"Unknown")+'</strong></div><div class="tile"><span>CASH EXPOSURE</span><strong>'+ (f.exposure!==null?money(f.exposure):"Unknown")+'</strong></div><div class="tile"><span>GATES</span><strong>'+g.checks.filter(c=>c.pass).length+'/'+g.checks.length+' passed</strong></div></div><div class="notice '+(g.passed?"success":"warning")+'">'+(g.passed?"All screening gates currently pass based on owner-entered data. Independent diligence still required.":"Not approval-ready: "+esc(g.checks.filter(c=>!c.pass).slice(0,2).map(c=>c.label).join("; ")))+'</div><div class="button-row" style="margin-top:15px">'+btn("Inspect dossier","open-opp",d.id,"btn-sm btn-ghost")+btn("Approve research","approve-research",d.id,"btn-sm btn-ghost")+(g.passed?btn("Approve draft prep","approve-draft",d.id,"btn-sm btn-primary"):"")+btn("Pass","pass-opp",d.id,"btn-sm btn-danger")+'</div></article>'}).join(""):'<div class="panel empty-state">Decision queue is clear. No candidates yet.</div>')+
 '<p class="small">*Forecast contribution is not received money. Demo figures are scenarios only. An owner-entered verified checkbox is not an independent professional verification.</p>';}
function renderSources(){return header("ORIGINAL EVIDENCE FIRST","Intelligence sources","Official procurement channels, partner research and historic award information—not simulated live feeds.",btn("＋ Add from source","add-opp","","btn-primary"))+
 '<div class="notice" style="margin-bottom:19px">Public notices require a secure, owner-configured feed adapter before they can be automatically imported. The dashboard never invents live leads. Source links open the official or named sites.</div>'+
 '<div class="grid two">'+SOURCES.map(s=>'<article class="source-item"><div class="card-head"><h3>'+esc(s.name)+'</h3>'+tag(s.phase,s.phase==="Backend"?"amber":"muted")+'</div><div class="item-meta">'+esc(s.kind)+'</div><p>'+esc(s.note)+'</p><a class="text-link" target="_blank" rel="noopener noreferrer" href="'+esc(safeUrl(s.url))+'">Open source ↗</a></article>').join("")+'</div>'+
 '<div class="panel" style="margin-top:20px"><h2>How Watchtower will verify an opportunity</h2><p class="panel-sub">Original URL → issuer and buyer identity → active deadline → published requirements → budget or purchase intent → eligible delivery structure → independently verified vendor quotes → cash-flow model → owner decision.</p></div>';}
function renderSettings(){return header("FOUNDER PARAMETERS","Rules & settings","Control what gets evaluated. Core financial guardrails are fixed in this public prototype.",btn("↓ Export real-workspace backup","export-json"))+
 '<div class="grid two"><section class="panel"><div class="panel-title"><h2>Workspace mode</h2>'+tag("BROWSER ONLY","amber")+'</div><p class="panel-sub">Switch between fictional demonstrations and your real manually entered research. Data is not synced between devices.</p><div class="radio-pair" role="group" aria-label="Workspace mode"><button class="'+(state.mode==="demo"?"selected":"")+'" data-action="mode-demo" type="button">DEMO SANDBOX</button><button class="'+(state.mode==="live"?"selected":"")+'" data-action="mode-live" type="button">LIVE WORKSPACE</button></div><div class="vdiv"></div>'+rowDetail("Real opportunities",String(state.live.opportunities.length))+rowDetail("Real vendor candidates",String(state.live.vendors.length))+rowDetail("Cash transactions recorded",String(state.live.transactions.length))+'</section>'+
 '<section class="panel"><div class="panel-title"><h2>Hard guardrails</h2>'+tag("LOCKED IN MVP","blue")+'</div>'+rowDetail("Per-deal capital limit",money(LIMITS.perDealExposure))+rowDetail("Aggregate active capital limit",money(LIMITS.portfolioExposure))+rowDetail("Minimum contribution margin",LIMITS.minMargin+"%")+rowDetail("Owner work goal",LIMITS.maxOwnerHours+" hours/week")+rowDetail("Monthly contribution goal",money(LIMITS.monthlyTarget))+'<p class="small" style="margin:15px 0 0">To change a hard guardrail, review the product specification and update the versioned finance policy. A browser UI change must never bypass it.</p></section></div>'+
 '<section class="panel" style="margin-top:18px"><h2>Data and backups</h2><p class="panel-sub">GitHub Pages has no private database. Use exports for your non-sensitive research. Imports replace the real workspace after confirmation.</p><div class="button-row">'+btn("↓ Export backup","export-json","","btn-primary")+btn("↑ Import backup","import-json")+btn("Reset demo scenarios","reset-demo")+btn("Clear real workspace","clear-live","","btn-danger")+'</div><input type="file" accept=".json,application/json" id="backupFile" hidden><div class="notice danger" style="margin-top:17px">Never store API keys, banking information, confidential proposals, vendor agreements or sensitive customer records in this prototype. Its JavaScript source and hosting are public.</div></section>'+
 '<section class="panel" style="margin-top:18px"><h2>What becomes automated later</h2><div class="grid three">'+[{h:"Source sync",d:"SAM.gov via a secure backend, deduplication and evidence records"},{h:"Private partner vault",d:"Authenticated profiles, verified documents, quotes and performance history"},{h:"AI research agent",d:"Source-backed opportunity summaries, alerts and five-item weekly brief"}].map(a=>'<div class="source-item"><h3>'+a.h+'</h3><p>'+a.d+'</p>'+tag("BACKEND PHASE","muted")+'</div>').join("")+'</div></section>';}
function fText(label,name,value="",hint="",required=false,type="text",attrs=""){return '<div class="field"><label for="f-'+esc(name)+'">'+esc(label)+'</label><input class="input" id="f-'+esc(name)+'" name="'+esc(name)+'" type="'+type+'" value="'+esc(value??"")+'" '+(required?"required ":"")+attrs+'>'+ (hint?'<small>'+esc(hint)+'</small>':'')+'</div>';}
function fSelect(label,name,choices,current=""){return '<div class="field"><label for="f-'+esc(name)+'">'+esc(label)+'</label><select id="f-'+esc(name)+'" name="'+esc(name)+'" class="select">'+choices.map(([k,v])=>'<option value="'+esc(k)+'" '+(k===current?"selected":"")+'>'+esc(v)+'</option>').join("")+'</select></div>';}
function fArea(label,name,value="",hint=""){return '<div class="field full"><label for="f-'+esc(name)+'">'+esc(label)+'</label><textarea id="f-'+esc(name)+'" name="'+esc(name)+'" class="textarea" maxlength="3000">'+esc(value||"")+'</textarea>'+(hint?'<small>'+esc(hint)+'</small>':"")+'</div>';}
function fCheck(label,name,checked=false){return '<label style="display:flex;gap:9px;align-items:flex-start;font-size:11px;color:var(--muted);line-height:1.5"><input type="checkbox" name="'+esc(name)+'" '+(checked?"checked":"")+' style="accent-color:var(--mint2);margin-top:2px"> <span>'+esc(label)+'</span></label>';}
function openModal(title,subtitle,body,wide=false){previousFocus=document.activeElement;modalRoot.innerHTML='<div class="modal-backdrop" data-action="backdrop"><section class="modal '+(wide?"modal-wide":"")+'" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><div><h2 id="modalTitle">'+esc(title)+'</h2><p>'+esc(subtitle)+'</p></div><button class="close-btn" data-action="close-modal" type="button" aria-label="Close dialog">×</button></div>'+body+'</section></div>';document.body.style.overflow="hidden";modalRoot.querySelector(".close-btn")?.focus();}
function closeModal(){modalRoot.innerHTML="";document.body.style.overflow="";detailId=null;previousFocus?.focus?.();}
function opportunityForm(id=null){const d=id?opportunities().find(x=>x.id===id):null;const a=d||{};const options=[["","No vendor assigned"],...vendors().map(v=>[v.id,v.name+(v.demo?" — DEMO":"")])];
const body='<form id="opportunityForm" data-edit-id="'+esc(id||"")+'"><div class="form-grid">'+fText("Opportunity title","title",a.title||"","Use the actual RFP title or a clear internal name.",true)+fSelect("Sector","sector",Object.entries(SECTORS),a.sector||"digital")+fText("Buyer / issuer","buyer",a.buyer||"","Record the real customer when known.")+fText("Source / channel","source",a.source||"","e.g., SAM.gov, client email, direct lead")+fText("Original source URL","sourceUrl",a.sourceUrl||"","Only http(s) links; use the official notice when possible.",false,"url")+fText("Deadline","deadline",a.deadline||"","Leave blank when not applicable.",false,"date")+fText("Last original-source verification","sourceCheckedAt",a.sourceCheckedAt||"","",false,"date")+ '<div class="field full"><label for="f-description">Scope / problem</label><textarea id="f-description" name="description" class="textarea" placeholder="What is the actual buyer requesting?">'+esc(a.description||"")+'</textarea></div>'+fText("Required skills (comma separated)","skills",(a.skills||[]).join(", "),"e.g. automation, web development, crm")+fSelect("Delivery partner","vendorId",options,a.vendorId||"")+
 '</div><div class="vdiv"></div><h3>Deal economics <span class="tiny">UNKNOWN IS OK; UNKNOWN NEVER PASSES APPROVAL</span></h3><div class="form-grid">'+
 fText("Customer contract value ($)","price",a.price??"","Quoted or hypothetical? Confirm before approval.",false,"number",'min="0" step="0.01"')+
 fText("Vendor quoted cost ($)","vendorCost",a.vendorCost??"","Leave blank until actual quote is known.",false,"number",'min="0" step="0.01"')+
 fText("Other direct costs ($)","otherCost",a.otherCost??"","Software, QA, materials, onboarding.",false,"number",'min="0" step="0.01"')+
 fText("Contingency reserve ($)","contingency",a.contingency??"","Included in conservative exposure.",false,"number",'min="0" step="0.01"')+
 fText("Vendor payment before next collectible milestone ($)","vendorUpfront",a.vendorUpfront??"","Required for the cash-exposure test.",false,"number",'min="0" step="0.01"')+
 fText("Other upfront outlays ($)","otherUpfront",a.otherUpfront??"","Non-vendor outlays before collection.",false,"number",'min="0" step="0.01"')+
 fText("Proposed client deposit ($)","clientDeposit",a.clientDeposit??"","For reference only; deposits are NOT netted from risk.",false,"number",'min="0" step="0.01"')+
 fText("Estimated owner work hours / week","weeklyHours",a.weeklyHours??"","Must fit ≤2 hours or be delegated.",false,"number",'min="0" step="0.1"')+
 '</div><div class="vdiv"></div><h3>Evidence and manual due diligence <span class="tiny">SELF-DECLARED, NOT AUDITED</span></h3><div class="grid two">'+fCheck("I checked the original source and its details","verifiedSource",a.verifiedSource)+fCheck("I confirmed the buyer or issuer identity","buyerVerified",a.buyerVerified)+fCheck("I received a genuine written vendor quote","quoteVerified",a.quoteVerified)+fCheck("I reviewed client and subcontractor terms","termsVerified",a.termsVerified)+fCheck("I reviewed compliance, licenses and obligations","complianceChecked",a.complianceChecked)+fCheck("Government subcontracting/eligibility reviewed (if applicable)","governmentReview",a.governmentReview)+'</div><div class="form-grid" style="margin-top:16px">'+
 fArea("Original source verification notes","sourceEvidence",a.sourceEvidence||"","Include official posting, date and document reference.")+
 fArea("Buyer identity verification notes","buyerEvidence",a.buyerEvidence||"","How was the actual buyer independently confirmed?")+
 fText("Written quote received on","quoteDate",a.quoteDate||"","",false,"date")+
 fArea("Written quote reference and scope","quoteEvidence",a.quoteEvidence||"","Record quote number / scope, not confidential documents.")+
 fArea("Client and vendor payment terms analysis","termsEvidence",a.termsEvidence||"","Include refund liability, milestone timing and change orders.")+
 fArea("Compliance / insurance / licenses assessment","complianceEvidence",a.complianceEvidence||"","Record which obligations were checked.")+
 '</div><fieldset style="margin-top:16px"><legend>Government contract diligence (if relevant)</legend><div class="form-grid">'+
 fText("NAICS classification","naicsCode",a.naicsCode||"","Six-digit code")+
 fText("Set-aside category","setAsideType",a.setAsideType||"","Enter the actual published status, or None.")+
 fArea("Subcontracting and prime delivery requirements","subcontractingNotes",a.subcontractingNotes||"","Review solicitation-specific restrictions.")+
 fArea("Government eligibility assessment","governmentReviewEvidence",a.governmentReviewEvidence||"","Source/date of eligibility and contracting review.")+
 '</div></fieldset><div class="vdiv"></div><h3>Projected cash milestones (optional)</h3><p class="small">One event per line: YYYY-MM-DD | receipt or expense | amount | purpose. Future receipts are assumptions, not risk-free deposits.</p>'+
 fArea("Cash-flow scenario","cashPlanText",(a.cashPlan||[]).map(x=>[x.date,x.type,x.amount,x.note||""].join(" | ")).join("\n"),"Only a visualization. The conservative capital cap still applies.")+'<div class="modal-foot">'+btn("Cancel","close-modal")+ '<button class="btn btn-primary" type="submit">Save opportunity</button></div></form>';
openModal(d?"Edit opportunity":"Add opportunity","Research intake · save only · no outreach or binding commitments",body,true);
}
function vendorForm(id=null){const v=id?vendors().find(x=>x.id===id):null,a=v||{};const body='<form id="vendorForm" data-edit-id="'+esc(id||"")+'"><div class="form-grid">'+fText("Company name","name",a.name||"","Enter actual legal / trade name if available.",true)+fText("Location / service area","city",a.city||"")+fText("Company website","website",a.website||"","Use the real supplier website.",false,"url")+fText("Skills (comma separated)","skills",(a.skills||[]).join(", "))+fText("Indicative delivery cost ($)","estimatedCost",a.estimatedCost??"","Until a signed quote is received, this is only a reference.",false,"number",'min="0" step="0.01"')+fSelect("Availability","availability",[["unknown","Unknown"],["available","Available — manually confirmed"],["busy","Busy"],["unavailable","Unavailable"]],a.availability||"unknown")+'<div class="field full"><label for="f-notes">Qualification notes</label><textarea class="textarea" id="f-notes" name="notes">'+esc(a.notes||"")+'</textarea></div></div><div class="vdiv"></div><div class="grid two">'+fCheck("Company identity and capabilities manually verified","verified",a.verified)+fCheck("References or portfolio validated","referencesChecked",a.referencesChecked)+fCheck("Responsiveness and communication reviewed","communicationChecked",a.communicationChecked)+fCheck("Actual written quote verified","quoteVerified",a.quoteVerified)+'</div><div class="modal-foot">'+btn("Cancel","close-modal")+'<button type="submit" class="btn btn-primary">Save partner</button></div></form>';openModal(v?"Review partner":"Add execution partner","Candidate directory · due diligence required before engagement",body,true);}
function detail(id,tab="overview"){const d=opportunities().find(x=>x.id===id);if(!d){toast("Opportunity not found",true);return;}detailId=id;detailTab=tab;
 const exposure=activePortfolioExposure(opportunities(),d.id),{g,f,score}=financialStatus(d,exposure),matches=matchVendors(d,vendors()).slice(0,3),transactions=work().transactions.filter(t=>t.dealId===d.id);
 const tabs=[["overview","Overview"],["financial","Financial model"],["partners","Vendor matches"],["gates","Risk gates"],["cash","Cash ledger"]];
 const tabHTML='<div class="tab-row" role="tablist">'+tabs.map(([k,v])=>'<button type="button" class="tab '+(tab===k?"active":"")+'" data-action="detail-tab" data-tab="'+k+'" role="tab" aria-selected="'+(tab===k)+'">'+v+'</button>').join("")+'</div>';
 let body="";
 if(tab==="overview")body='<div class="grid two"><div class="panel"><h3>Buyer / source</h3>'+rowDetail("Buyer",esc(d.buyer||"Unknown"))+rowDetail("Sector",esc(SECTORS[d.sector]||"Other"))+rowDetail("Deadline",esc(dateFmt(d.deadline)))+rowDetail("Source",esc(d.source||"Unknown"))+'<div class="statline"><span>Original evidence</span>'+sourceLink(d)+'</div></div><div class="panel"><h3>Research status</h3>'+rowDetail("Priority score",String(score)+"/100")+rowDetail("Stage",esc(d.stage.replaceAll("_"," ")))+rowDetail("Screening gates",g.checks.filter(c=>c.pass).length+"/"+g.checks.length+" pass")+rowDetail("Workspace",d.demo?"FICTIONAL EXAMPLE":"Self-reported research")+'</div></div><div class="panel" style="margin-top:14px"><h3>Scope / hypothesis</h3><p class="panel-sub">'+esc(d.description||"No scope added yet.")+'</p><div class="vendor-skills">'+(d.skills||[]).map(s=>'<span class="skill">'+esc(s)+'</span>').join("")+'</div></div>';
 if(tab==="financial")body='<div class="grid two"><div class="panel"><h3>Project economics</h3>'+rowDetail("Customer price",f.price!==null?money(f.price):"Unknown")+rowDetail("Supplier cost",f.vendorCost!==null?money(f.vendorCost):"Unknown")+rowDetail("Other direct costs",f.otherCost!==null?money(f.otherCost):"Unknown")+rowDetail("Contingency reserve",f.reserve!==null?money(f.reserve):"Unknown")+rowDetail("Forecast contribution",f.known?'<span class="money">'+money(f.contribution)+'</span>':"Unknown")+rowDetail("Contribution margin",f.known?f.margin.toFixed(1)+"%":"Unknown")+'</div><div class="panel"><h3>Company cash exposure</h3>'+rowDetail("Vendor upfront",numberOrNull(d.vendorUpfront)!==null?money(d.vendorUpfront):"Unknown")+rowDetail("Other upfront",numberOrNull(d.otherUpfront)!==null?money(d.otherUpfront):"Unknown")+rowDetail("Contingency held",f.reserve!==null?money(f.reserve):"Unknown")+rowDetail("Conservative exposure",f.exposure!==null?money(f.exposure):"Unknown")+rowDetail("Other committed portfolio exposure",money(exposure))+rowDetail("Cash cap",money(LIMITS.portfolioExposure))+'<div class="notice warning" style="margin-top:16px">Proposed deposit '+money(f.clientDeposit)+' is NOT counted as risk-free capital. Actual contract terms, refund liability and payment timing require review.</div></div></div><div class="notice" style="margin-top:12px">These numbers are owner-entered or fictional examples. No pricing engine has authenticated customer quotes or vendor invoices.</div>'+renderWaterfall(d);
 if(tab==="partners")body='<div class="notice" style="margin-bottom:14px">Supplier scores rank matching skills and available evidence, not contractual eligibility. Names in demo mode are fictional. A listed firm has not agreed to any work.</div>'+(matches.length?matches.map(v=>'<div class="decision-card"><div class="card-head"><div><h3>'+esc(v.name)+'</h3><p class="small">'+esc(v.city||"Location unknown")+'</p></div><span class="score-circle">'+v.matchScore+'</span></div><div class="vendor-skills">'+v.matchedSkills.map(x=>'<span class="skill">'+esc(x)+'</span>').join("")+'</div>'+rowDetail("Indicative cost",numberOrNull(v.estimatedCost)!==null?money(v.estimatedCost):"Unknown")+rowDetail("Status",v.verified?"Manually checked candidate":"Unverified candidate")+rowDetail("Delivery",esc(v.availability||"unknown"))+'<p class="small">Missing capabilities: '+esc(v.missing.join(", ")||"none identified")+'</p>'+btn("Assign as preferred candidate","assign-vendor",d.id,"btn-sm btn-ghost",'data-vendor="'+esc(v.id)+'"')+'</div>').join(""):'<div class="empty-state">No delivery partners in this workspace. Add real firms and their skills to build a shortlist.</div>');
 if(tab==="gates")body='<div class="notice '+(g.passed?"success":"warning")+'">'+(g.passed?"All automated research gates pass on entered evidence. Formal due diligence remains necessary.":"Not ready for proposal preparation. Resolve every blocking check before advancing.")+'</div><div class="panel" style="margin-top:14px">'+g.checks.map(c=>'<div class="gate"><div><strong>'+esc(c.label)+'</strong><div class="gate-text">'+esc(c.detail)+'</div></div>'+tag(c.pass?"PASS":"BLOCKED",c.pass?"":"red")+'</div>').join("")+'</div><p class="small" style="margin-top:13px">The checks do not constitute legal advice, independent identity verification or formal procurement certification.</p>';
 if(tab==="cash")body='<div class="notice">Realized contribution = recorded cash receipts less recorded direct cash expenses. These are manual records and do not imply bank reconciliation. Forecast profit is never counted here.</div><div class="panel" style="margin-top:14px"><div class="panel-title"><h2>Recorded cash activity</h2>'+btn("＋ Add cash entry","add-transaction",d.id,"btn-sm btn-primary")+'</div>'+rowDetail("Recorded net contribution",'<span class="money">'+money(realizedContribution(work().transactions,d.id))+'</span>')+(transactions.length?'<div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Type</th><th>Amount</th><th>Note</th></tr></thead><tbody>'+transactions.map(t=>'<tr><td>'+esc(dateFmt(t.date))+'</td><td>'+esc(t.type)+'</td><td>'+money(t.amount)+'</td><td>'+esc(short(t.note||"",45))+'</td></tr>').join("")+'</tbody></table></div>':'<p class="small">No actual cash entries recorded.</p>')+'</div>';
 const bottom='<div class="modal-foot">'+btn("Edit dossier","edit-opp",d.id)+btn("Approve research","approve-research",d.id)+btn("Close","close-modal","","btn-primary")+'</div>';
 const modalBody=tabHTML+body+bottom;
 // Reuse modal where possible but ensure escape+focus are preserved.
 const already=modalRoot.querySelector(".modal");
 if(already){const saved=previousFocus;openModal(d.title,(d.demo?"FICTIONAL SANDBOX • ":"RESEARCH DOSSIER • ")+esc(d.buyer||"Buyer unknown"),modalBody,true);previousFocus=saved;}
 else openModal(d.title,(d.demo?"FICTIONAL SANDBOX • ":"RESEARCH DOSSIER • ")+(d.buyer||"Buyer unknown"),modalBody,true);
}
function renderWaterfall(d){const w=forecastCashWaterfall(d);if(!w.complete)return '<div class="panel" style="margin-top:15px"><h3>Cash-flow waterfall</h3><p class="small">No milestone scenario yet. Edit the dossier to add expected receipts and supplier payments. The hard capital gate remains independent.</p></div>';return '<div class="panel" style="margin-top:15px"><div class="panel-title"><h2>Forecast cash waterfall</h2>'+tag("SCENARIO ONLY","amber")+'</div>'+rowDetail("Peak projected funding gap",money(w.peakProjectedFundingGap))+rowDetail("Expected inflows",money(w.totalReceipts))+rowDetail("Expected outflows",money(w.totalOutflows))+'<div class="notice warning">Future receipts are NOT bank-confirmed or used to reduce the conservative funding gate.</div><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Kind</th><th>Amount</th><th>Running balance</th><th>Note</th></tr></thead><tbody>'+w.timeline.map(x=>'<tr><td>'+esc(dateFmt(x.date))+'</td><td>'+esc(x.type)+'</td><td>'+money(x.amount)+'</td><td>'+money(x.runningBalance)+'</td><td>'+esc(short(x.note,50))+'</td></tr>').join("")+'</tbody></table></div></div>';}
function transactionForm(dealId){const d=opportunities().find(x=>x.id===dealId);if(!d)return;const content='<form id="transactionForm" data-deal-id="'+esc(dealId)+'"><div class="form-grid">'+fSelect("Actual cash movement","type",[["receipt","Customer payment received"],["expense","Direct project expense paid"]],"receipt")+fText("Amount ($)","amount","","Actual cash amount; not a forecast.",true,"number",'min="0.01" step="0.01"')+fText("Date","date",new Date().toISOString().slice(0,10),"",true,"date")+fText("Note / reference","note","","Do not include confidential banking details.")+'</div><div class="modal-foot">'+btn("Cancel","close-modal")+'<button type="submit" class="btn btn-primary">Record cash entry</button></div></form>';openModal("Record cash movement",d.title+" · owner-entered actual transaction",content);}
function toast(message,error=false){const host=document.getElementById("toastRegion"),node=document.createElement("div");node.className="toast"+(error?" error":"");node.textContent=message;host.appendChild(node);setTimeout(()=>node.remove(),4500);}
function closeNav(){sidebar.classList.remove("open");document.getElementById("mobileOverlay").hidden=true;document.getElementById("mobileMenu").setAttribute("aria-expanded","false");}
function toggleNav(){const open=!sidebar.classList.contains("open");sidebar.classList.toggle("open",open);document.getElementById("mobileOverlay").hidden=!open;document.getElementById("mobileMenu").setAttribute("aria-expanded",String(open));}
function upsertDealFromForm(form){const fd=new FormData(form),old=opportunities().find(d=>d.id===form.dataset.editId),o=old?{...old}:{};const skills=String(fd.get("skills")||"").split(",").map(x=>x.trim()).filter(Boolean).slice(0,25);
 const u=String(fd.get("sourceUrl")||"").trim();if(u&&!safeUrl(u)){toast("Only HTTP(S) source URLs are permitted",true);return;}
 const cashLines=String(fd.get("cashPlanText")||"").trim().split(/\r?\n/).filter(Boolean);if(cashLines.length>30){toast("Maximum 30 scenario milestones",true);return;}let cashPlan=[];for(const line of cashLines){const [date,type,amount,...note]=line.split("|").map(x=>x.trim());if(!/^\d{4}-\d{2}-\d{2}$/.test(date||"")||!["receipt","expense"].includes(type)||numberOrNull(amount)===null){toast("Cash line format: YYYY-MM-DD | receipt/expense | amount | note",true);return;}cashPlan.push({date,type,amount:Number(amount),note:note.join("|").slice(0,120)});}
 Object.assign(o,{id:o.id||uuid("op"),demo:state.mode==="demo",title:String(fd.get("title")||"").trim().slice(0,180),sector:fd.get("sector"),buyer:String(fd.get("buyer")||"").trim().slice(0,160),source:String(fd.get("source")||"").trim().slice(0,120),sourceUrl:safeUrl(u),deadline:String(fd.get("deadline")||""),description:String(fd.get("description")||"").slice(0,3000),skills,vendorId:String(fd.get("vendorId")||""),weeklyHours:String(fd.get("weeklyHours")||""),sourceCheckedAt:String(fd.get("sourceCheckedAt")||""),quoteDate:String(fd.get("quoteDate")||""),cashPlan,createdAt:o.createdAt||new Date().toISOString(),stage:o.stage||"NEW",decision:o.decision||"research"});
 for(const name of ["price","vendorCost","otherCost","contingency","vendorUpfront","otherUpfront","clientDeposit"])o[name]=String(fd.get(name)??"");
 for(const name of ["sourceEvidence","buyerEvidence","quoteEvidence","termsEvidence","complianceEvidence","naicsCode","setAsideType","subcontractingNotes","governmentReviewEvidence"])o[name]=String(fd.get(name)||"").slice(0,3000);
 for(const name of ["verifiedSource","buyerVerified","quoteVerified","termsVerified","complianceChecked","governmentReview"])o[name]=fd.get(name)==="on";
 if(o.demo){o.verifiedSource=false;o.buyerVerified=false;o.quoteVerified=false;}
 if(!o.title){toast("Opportunity title is required",true);return;}
 if(old)Object.assign(old,o);else opportunities().unshift(o);
 log((old?"Updated":"Added")+" opportunity: "+o.title,o.id);save();closeModal();render();toast("Opportunity saved in "+(state.mode==="demo"?"sandbox":"local workspace"));}
function upsertVendorFromForm(form){const fd=new FormData(form),old=vendors().find(v=>v.id===form.dataset.editId),v=old?{...old}:{};const u=String(fd.get("website")||"").trim();if(u&&!safeUrl(u)){toast("Only HTTP(S) websites are permitted",true);return;}
 Object.assign(v,{id:v.id||uuid("vendor"),demo:state.mode==="demo",name:String(fd.get("name")||"").trim().slice(0,160),city:String(fd.get("city")||"").trim().slice(0,120),website:safeUrl(u),skills:String(fd.get("skills")||"").split(",").map(x=>x.trim()).filter(Boolean).slice(0,25),estimatedCost:String(fd.get("estimatedCost")??""),availability:String(fd.get("availability")||"unknown"),notes:String(fd.get("notes")||"").slice(0,2000)});
 for(const name of ["verified","referencesChecked","communicationChecked","quoteVerified"])v[name]=fd.get(name)==="on";
 if(v.demo){v.verified=false;v.quoteVerified=false;}
 if(!v.name){toast("Company name is required",true);return;}
 if(old)Object.assign(old,v);else vendors().unshift(v);
 log((old?"Updated":"Added")+" candidate partner: "+v.name);save();closeModal();render();toast("Partner saved (not contacted)");}
function upsertTransaction(form){if(state.mode==="demo"){toast("Demo mode cannot record actual income. Switch to Live workspace.",true);return;}const fd=new FormData(form),amount=numberOrNull(fd.get("amount"));if(amount===null||amount<=0){toast("Enter a positive cash amount",true);return;}const dealId=form.dataset.dealId;work().transactions.unshift({id:uuid("txn"),dealId,type:fd.get("type")==="receipt"?"receipt":"expense",amount,date:String(fd.get("date")||new Date().toISOString().slice(0,10)),note:String(fd.get("note")||"").slice(0,160)});log("Recorded actual "+String(fd.get("type"))+" "+money(amount),dealId);save();closeModal();render();toast("Cash entry recorded locally");}
function changeDecision(id,action){const d=opportunities().find(x=>x.id===id);if(!d)return;
 if(action==="approve-draft"){const gates=evaluateGates(d,vendors(),activePortfolioExposure(opportunities(),id));if(!gates.passed){toast("Risk gates block proposal preparation",true);return;}if(!confirm("Approve preparing a proposal draft? This will NOT send any proposal or create a contract."))return;d.stage="OWNER_APPROVAL";d.decision="draft-approved";log("Approved local proposal DRAFT preparation: "+d.title,id);}
 else if(action==="approve-research"){d.decision="investigate";if(d.stage==="NEW")d.stage="PRELIMINARY_FIT";log("Owner approved research ONLY: "+d.title,id);}
 else if(action==="pass-opp"){if(!confirm("Archive this opportunity from active review?"))return;d.stage="ARCHIVED";d.decision="pass";log("Passed on opportunity: "+d.title,id);}
 save();closeModal();render();toast("Decision recorded locally; no external action taken.");}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportJSON(){const backup={schema:"watchtower-local-backup-v1",exportedAt:new Date().toISOString(),live:state.live};download("watchtower-live-backup-"+new Date().toISOString().slice(0,10)+".json",JSON.stringify(backup,null,2),"application/json");toast("Exported real-workspace backup (no demo examples).");}
function exportBrief(){const top=opportunities().filter(d=>!["ARCHIVED","LOST"].includes(d.stage)).sort((a,b)=>scoreOpportunity(b,vendors())-scoreOpportunity(a,vendors())).slice(0,5);const lines=["# WATCHTOWER / OWNER DECISION BRIEF","","Created: "+new Date().toISOString(),"Status: "+(state.mode==="demo"?"FICTIONAL DEMO":"Owner-entered research, not independently audited"),"Not an authorization for contracts, payments or proposals.",""];for(const d of top){const g=evaluateGates(d,vendors(),activePortfolioExposure(opportunities(),d.id)),f=g.finance;lines.push("## "+d.title,"- Buyer: "+(d.buyer||"Unknown"),"- Source: "+(safeUrl(d.sourceUrl)||"Missing"),"- Deadline: "+(d.deadline||"Unknown"),"- Forecast contribution: "+(f.known?money(f.contribution):"Unknown"),"- Conservative exposure: "+(f.exposure!==null?money(f.exposure):"Unknown"),"- Research score: "+scoreOpportunity(d,vendors())+"/100","- Gates passed: "+g.checks.filter(x=>x.pass).length+"/"+g.checks.length,"- Next checks:",...g.checks.filter(x=>!x.pass).map(x=>"  - "+x.label+": "+x.detail),"");}download("watchtower-weekly-brief-"+new Date().toISOString().slice(0,10)+".md",lines.join("\n"),"text/markdown");toast("Brief exported for owner review.");}
function exportCSV(){const fields=["title","buyer","sector","source","sourceUrl","deadline","stage","price","vendorCost","vendorUpfront"],csv=[fields.join(","),...filtered().map(d=>fields.map(k=>'"'+String(d[k]??"").replaceAll('"','""')+'"').join(","))].join("\r\n");download("watchtower-opportunity-export.csv",csv,"text/csv;charset=utf-8");toast("Exported visible opportunities as CSV");}
function validateBackup(x){return x&&x.schema==="watchtower-local-backup-v1"&&x.live&&["opportunities","vendors","transactions","activity"].every(k=>Array.isArray(x.live[k])&&x.live[k].length<=500)&&x.live.opportunities.every(d=>d&&typeof d.title==="string"&&typeof d.id==="string")&&x.live.vendors.every(v=>v&&typeof v.id==="string"&&typeof v.name==="string")&&x.live.transactions.every(t=>t&&["receipt","expense"].includes(t.type)&&numberOrNull(t.amount)!==null);}
async function importBackup(file){if(!file)return;if(file.size>1024*1024){toast("Backup exceeds 1MB import limit",true);return;}try{const x=JSON.parse(await file.text());if(!validateBackup(x))throw Error("Invalid backup schema");if(!confirm("Replace your LOCAL real workspace with this backup? Existing browser-only live records will be overwritten."))return;state.live={opportunities:x.live.opportunities.map(d=>({...d,demo:false})),vendors:x.live.vendors.map(v=>({...v,demo:false})),transactions:x.live.transactions,activity:x.live.activity};state.mode="live";save();render();toast("Backup imported into local workspace");}catch(err){toast("Import failed: "+String(err.message||"Invalid file"),true);}}
function handleAction(node){const action=node.dataset.action,id=node.dataset.id;
 switch(action){
 case"add-opp":opportunityForm();break;
 case"edit-opp":opportunityForm(id);break;
 case"open-opp":detail(id);break;
 case"detail-tab":detail(detailId,node.dataset.tab);break;
 case"add-vendor":vendorForm();break;
 case"edit-vendor":vendorForm(id);break;
 case"assign-vendor":{const d=opportunities().find(x=>x.id===id);if(d){d.vendorId=node.dataset.vendor;d.quoteVerified=false;log("Preferred candidate assigned for research: "+d.title,id);save();detail(id,"partners");toast("Vendor assigned; written quote still required");}break;}
 case"add-transaction":transactionForm(id);break;
 case"approve-research":case"approve-draft":case"pass-opp":changeDecision(id,action);break;
 case"close-modal":closeModal();break;
 case"backdrop":closeModal();break;
 case"go-hunt":setView("hunt");break;
 case"go-settings":setView("settings");break;
 case"mode-demo":state.mode="demo";save();render();toast("Demo sandbox activated");break;
 case"mode-live":state.mode="live";save();render();toast("Live workspace activated — data stays local");break;
 case"export-json":exportJSON();break;
 case"export-csv":exportCSV();break;
 case"export-brief":exportBrief();break;
 case"go-sources":setView("sources");break;
 case"import-json":document.getElementById("backupFile")?.click();break;
 case"reset-demo":if(confirm("Reset fictional demo examples and decisions?")){state.demo={opportunities:clone(DEMO_OPPORTUNITIES),vendors:clone(DEMO_VENDORS),transactions:[],activity:[]};save();render();toast("Demo restored");}break;
 case"clear-live":if(confirm("Permanently clear all local real-workspace records from THIS browser? Export a backup first.")){state.live={opportunities:[],vendors:[],transactions:[],activity:[]};save();render();toast("Local live workspace cleared");}break;
 }
}
document.addEventListener("click",event=>{const nav=event.target.closest("[data-view]");if(nav){event.preventDefault();setView(nav.dataset.view);return;}const node=event.target.closest("[data-action]");if(node){event.preventDefault();if(node.dataset.action==="backdrop"&&node!==event.target)return;handleAction(node);}});
modalRoot.addEventListener("submit",event=>{event.preventDefault();if(event.target.id==="opportunityForm")upsertDealFromForm(event.target);if(event.target.id==="vendorForm")upsertVendorFromForm(event.target);if(event.target.id==="transactionForm")upsertTransaction(event.target);});
document.addEventListener("change",event=>{if(event.target.id==="sectorFilter"){state.filters.sector=event.target.value;save();render();}if(event.target.id==="stageFilter"){state.filters.stage=event.target.value;save();render();}if(event.target.id==="backupFile"){importBackup(event.target.files?.[0]);event.target.value="";}});
document.addEventListener("input",event=>{if(!["huntSearch","partnerSearch"].includes(event.target.id))return;const id=event.target.id,pos=event.target.selectionStart;const key=id==="huntSearch"?"search":"partnerSearch";state.filters[key]=event.target.value;const out=id==="huntSearch"?document.getElementById("opportunityResults"):null;if(out)out.innerHTML=renderRows(filtered());if(id==="partnerSearch"){render();const next=document.getElementById(id);next?.focus();try{next?.setSelectionRange(pos,pos);}catch{}}save();});
document.addEventListener("keydown",event=>{if(event.key==="Escape"&&modalRoot.firstChild){closeModal();return;}if(event.key==="Tab"&&modalRoot.firstChild){const focus=Array.from(modalRoot.querySelectorAll('button:not([disabled]),[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled])')).filter(el=>el.getClientRects().length);if(!focus.length)return;const first=focus[0],last=focus.at(-1);if(event.shiftKey&&document.activeElement===first){last.focus();event.preventDefault();}else if(!event.shiftKey&&document.activeElement===last){first.focus();event.preventDefault();}}});
document.getElementById("mobileMenu").addEventListener("click",toggleNav);
document.getElementById("mobileOverlay").addEventListener("click",closeNav);
document.getElementById("exportTop").addEventListener("click",exportJSON);
window.addEventListener("hashchange",render);
render();
